True def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        marks = [i for i, value in enumerate(row) if value != 0]
        if len(marks) >= 2:
            for i in range(marks[0] + 1, marks[-1]):
                if row[i] == 0:
                    row[i] = 2
    return out
